import{_ as a,o as t,c as n,a5 as s}from"./chunks/framework.pJebtgMf.js";const h=JSON.parse('{"title":"AI 动态 · 2026-08-23","description":"","frontmatter":{"title":"AI 动态 · 2026-08-23","date":"2026-08-23T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-23.md","filePath":"news/2026-08/ai-news-2026-08-23.md","lastUpdated":null}'),r={name:"news/2026-08/ai-news-2026-08-23.md"};function o(i,e,l,c,p,d){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-08-23" tabindex="-1">AI 动态 · 2026-08-23 <a class="header-anchor" href="#ai-动态-·-2026-08-23" aria-label="Permalink to &quot;AI 动态 · 2026-08-23&quot;">​</a></h1><blockquote><p>截至 2026-08-23。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="英伟达ai服务器将涨价15-内存成本飙升-1gw数据中心成本激增50亿美元" tabindex="-1">英伟达AI服务器将涨价15%：内存成本飙升，1GW数据中心成本激增50亿美元 <a class="header-anchor" href="#英伟达ai服务器将涨价15-内存成本飙升-1gw数据中心成本激增50亿美元" aria-label="Permalink to &quot;英伟达AI服务器将涨价15%：内存成本飙升，1GW数据中心成本激增50亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-23">2026-08-23</time></p><p>据彭博社与 The Information 消息，英伟达已告知部分大客户，明年初交付的 AI 服务器（含 Grace Blackwell 和 Vera Rubin）价格将上调 15% 以上，部分系统涨幅约 17%。内存芯片成本飙升是主因，一座 1GW 级 AI 数据中心可能因此额外增加至少 50 亿美元建设成本。对读者：AI 基础设施采购成本将显著上升，建议提前规划预算并评估替代硬件方案。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/478164.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="openai-呼吁加州加强-ai-安全法案-sb-53" tabindex="-1">OpenAI 呼吁加州加强 AI 安全法案 SB 53 <a class="header-anchor" href="#openai-呼吁加州加强-ai-安全法案-sb-53" aria-label="Permalink to &quot;OpenAI 呼吁加州加强 AI 安全法案 SB 53&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-22">2026-08-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/eaf841b9e0bc.jpg" alt="配图"></p><p>OpenAI 一反此前立场，呼吁加州对去年通过的 AI 安全法案 SB 53 进行修订以加强保障，例如要求对前沿模型在训练或评估期间进行潜在严重事件监控，并加强整个模型开发生命周期的网络安全保护。对读者：AI 监管风向正在变化，企业应关注合规要求，提前调整模型开发与部署流程。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/22/openai-says-california-should-strengthen-its-ai-safety-bill/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="研究-前沿-ai-实验室仍不愿透露如何控制失控模型" tabindex="-1">研究：前沿 AI 实验室仍不愿透露如何控制失控模型 <a class="header-anchor" href="#研究-前沿-ai-实验室仍不愿透露如何控制失控模型" aria-label="Permalink to &quot;研究：前沿 AI 实验室仍不愿透露如何控制失控模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-22">2026-08-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/6a4bb712a9b1.jpg" alt="配图"></p><p>Guidelight AI Standards 的一项新研究发现，顶级 AI 实验室中很少有公开记录的控制（containment）响应计划。控制计划定义了当 AI 试图颠覆人类控制时，应切断哪些访问权限以及何时完全关闭系统。对读者：AI 安全与治理仍是关键议题，企业部署 AI 时应自行评估风险并制定应急预案。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/22/frontier-ai-labs-still-wont-say-how-theyd-contain-a-rogue-model/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="视频生成迎来-claude-code-时刻-minimax-design-杀入-adobe、canva-腹地" tabindex="-1">视频生成迎来“Claude Code 时刻”，MiniMax Design 杀入 Adobe、Canva 腹地 <a class="header-anchor" href="#视频生成迎来-claude-code-时刻-minimax-design-杀入-adobe、canva-腹地" aria-label="Permalink to &quot;视频生成迎来“Claude Code 时刻”，MiniMax Design 杀入 Adobe、Canva 腹地&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-22">2026-08-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/fd5d5360752e.jpg" alt="配图"></p><p>文章指出 AI 视频生成正从工具组合演进为端到端流水线，但多工具协同仍导致迭代效率瓶颈。营销内容需求激增与交付时效压缩形成矛盾，隐性成本集中在工具切换与重复适配。MiniMax Design 等产品试图以更一体化的方案切入，直接对标 Adobe、Canva 等传统设计工具。对读者：内容团队应关注端到端 AI 视频工作流，以降低多工具切换带来的隐性成本。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/7FAcAhVUw89VJNwuOwrc?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="gemini-3-7-flash、grok-4-6、glm-5-3-与-deepseek-v4-pro-加入前沿模型竞争" tabindex="-1">Gemini 3.7 Flash、Grok 4.6、GLM-5.3 与 DeepSeek V4 Pro 加入前沿模型竞争 <a class="header-anchor" href="#gemini-3-7-flash、grok-4-6、glm-5-3-与-deepseek-v4-pro-加入前沿模型竞争" aria-label="Permalink to &quot;Gemini 3.7 Flash、Grok 4.6、GLM-5.3 与 DeepSeek V4 Pro 加入前沿模型竞争&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Hacker News</span><time datetime="2026-08-23">2026-08-23</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/e5ac3c469229.png" alt="配图"></p><p>8月中旬多家大模型密集发布：Grok 4.6、Gemini 3.7 Flash、DeepSeek V4 Pro 0813 以及开源模型 Qwen3.8 Max、GLM-5.3 等。评测显示，闭源模型在 Baba Is Bench 等任务上表现惊艳，且成本较前代降低 3-20 倍；开源模型进展则相对渐进。对读者：关注新模型在推理与成本上的显著提升，可考虑将高性价比模型接入现有应用以降低运营成本。</p><p class="news-entry-source"><a href="https://quesma.com/blog/baba-is-aug-2026/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="meta-开源-300-亿参数端侧智能体模型-muse-glimmer" tabindex="-1">Meta 开源 300 亿参数端侧智能体模型 Muse Glimmer <a class="header-anchor" href="#meta-开源-300-亿参数端侧智能体模型-muse-glimmer" aria-label="Permalink to &quot;Meta 开源 300 亿参数端侧智能体模型 Muse Glimmer&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-22">2026-08-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/2f352fa13b24.jpg" alt="配图"></p><p>Meta AI Research 发布 Muse Glimmer，一款 300 亿参数的开放权重模型（Apache 2.0），专为本地工作流设计，支持视觉输入与工具调用。通过动态量化，模型占用可降至约 17-20 GB，配合 DFlash 推测解码，在消费级 GPU 上生成吞吐量可提升至多 3.1 倍。对读者：可在本地 GPU 上运行自主智能体，适合对数据隐私和延迟敏感的应用场景。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/aGfkSN1YlmLrUQMPea9L?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="deepmind-校友创立的-inherent-发布-ai-队友-faraday-称在复现研究任务上超越-anthropic-和-openai" tabindex="-1">DeepMind 校友创立的 Inherent 发布 AI“队友” Faraday，称在复现研究任务上超越 Anthropic 和 OpenAI <a class="header-anchor" href="#deepmind-校友创立的-inherent-发布-ai-队友-faraday-称在复现研究任务上超越-anthropic-和-openai" aria-label="Permalink to &quot;DeepMind 校友创立的 Inherent 发布 AI“队友” Faraday，称在复现研究任务上超越 Anthropic 和 OpenAI&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-22">2026-08-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/f3b4c48930d5.jpg" alt="配图"></p><p>伦敦 AI 实验室 Inherent 由 Google DeepMind 校友创立，发布 AI 智能体 Faraday，声称其复现科学论文的能力超越了 Anthropic 和 OpenAI 的更大模型，且模型规模更小。对读者：关注小型专业模型在特定任务上的潜力，可能以更低成本实现高效能。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/22/inherent-founded-by-deepmind-alumni-says-its-ai-teammate-just-outperformed-anthropic-and-openai-at-replicating-research/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="voltagent-awesome-agent-skills-收录-1000-个-agent-技能-兼容-claude-code、codex-等" tabindex="-1">VoltAgent/awesome-agent-skills：收录 1000+ 个 Agent 技能，兼容 Claude Code、Codex 等 <a class="header-anchor" href="#voltagent-awesome-agent-skills-收录-1000-个-agent-技能-兼容-claude-code、codex-等" aria-label="Permalink to &quot;VoltAgent/awesome-agent-skills：收录 1000+ 个 Agent 技能，兼容 Claude Code、Codex 等&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">VoltAgent/awesome-agent-skills</span><time datetime="2026-08-23">2026-08-23</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/fd54fc3d8360.png" alt="配图"></p><p>开源项目 awesome-agent-skills 收录了来自官方开发团队和社区的 1000 多个 Agent 技能，兼容 Claude Code、Codex、Gemini CLI、Cursor 等多种工具。对读者：可从中寻找现成的 Agent 技能，快速增强你的 AI 助手能力，避免重复造轮子。</p><p class="news-entry-source"><a href="https://github.com/VoltAgent/awesome-agent-skills" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="anthropic-发布-claude-插件社区市场-claude-plugins-community" tabindex="-1">Anthropic 发布 Claude 插件社区市场 claude-plugins-community <a class="header-anchor" href="#anthropic-发布-claude-插件社区市场-claude-plugins-community" aria-label="Permalink to &quot;Anthropic 发布 Claude 插件社区市场 claude-plugins-community&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">anthropics/claude-plugins-community</span><time datetime="2026-08-23">2026-08-23</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/bc9e09f57a7b.png" alt="配图"></p><p>Anthropic 推出 claude-plugins-community，这是一个面向 Claude Cowork 和 Claude Code 的社区插件市场（只读镜像），开发者可通过指定链接提交插件。对读者：可关注该插件市场，扩展 Claude Code 的功能，提升开发效率。</p><p class="news-entry-source"><a href="https://github.com/anthropics/claude-plugins-community" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="dynamodb-原生支持向量搜索-向量数据库要被取代" tabindex="-1">DynamoDB 原生支持向量搜索，向量数据库要被取代？ <a class="header-anchor" href="#dynamodb-原生支持向量搜索-向量数据库要被取代" aria-label="Permalink to &quot;DynamoDB 原生支持向量搜索，向量数据库要被取代？&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-23">2026-08-23</time></p><p>亚马逊云科技为 DynamoDB 推出原生向量搜索功能，允许开发者将嵌入向量与应用数据存储在同一张表中，并直接运行近似最近邻查询，无需再维护单独的向量数据库。该功能支持最多 4096 维向量、多种距离函数及内联过滤，采用无服务器模式自动扩展。对读者：构建 AI 应用时可优先考虑 DynamoDB 原生向量能力，简化架构并降低数据同步成本。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/9YicfQysexJdmx11xG4m?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="postgresql-太难懂-开源项目-pgsimcity-把它做成了城市模拟器" tabindex="-1">PostgreSQL 太难懂？开源项目 PGSimCity 把它做成了城市模拟器 <a class="header-anchor" href="#postgresql-太难懂-开源项目-pgsimcity-把它做成了城市模拟器" aria-label="Permalink to &quot;PostgreSQL 太难懂？开源项目 PGSimCity 把它做成了城市模拟器&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-23">2026-08-23</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/3e0d55d7f12a.jpg" alt="配图"></p><p>开发者 Nikolay Samokhvalov 发布 PGSimCity，一款开源教育可视化工具，将 PostgreSQL 18 集群的运行机制（如 shared_buffers、WAL、autovacuum 等）转换为交互式 3D 城市模拟，完全在浏览器中运行。项目使用 three.js 渲染，并集成 PGlite 在浏览器中运行真实 PostgreSQL。对读者：可通过该工具直观理解 PostgreSQL 内部机制，适合作为团队培训或学习辅助。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/umVdo2GaEyONQLWNmPZ9?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="cloudflare-推出-cache-response-rules-在源站响应后进一步控制缓存" tabindex="-1">Cloudflare 推出 Cache Response Rules，在源站响应后进一步控制缓存 <a class="header-anchor" href="#cloudflare-推出-cache-response-rules-在源站响应后进一步控制缓存" aria-label="Permalink to &quot;Cloudflare 推出 Cache Response Rules，在源站响应后进一步控制缓存&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-23">2026-08-23</time></p><p>Cloudflare 发布缓存响应规则（Cache Response Rules），这是一套新的规则引擎，运行在源站返回响应之后、内容写入缓存之前。它允许用户修改 Cache-Control 指令、管理 Cache Tag，并移除 Set-Cookie、ETag 等 Header，无需修改源站应用，从而提高缓存命中率并简化 CDN 迁移。对读者：可借此解决因意外 Header 导致缓存失效的问题，提升站点性能并降低源站带宽成本。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/kyUdCw0IPHwuIHg2WJCu?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const u=a(r,[["render",o]]);export{h as __pageData,u as default};
